counts=collections.defaultdict(list)
for r in load_history():
 if r['family']!='bigram_lm':continue
 q=r['question']; parts=re.split(r'### Choice ([A-E])\s*',q); cs=[]
 for i in range(1,len(parts),2):
  t=parts[i+1];op=re.search(r'- Optimizer: (\w+)',t);lr=re.search(r'- Learning rate: ([\deE.+-]+)',t);dm=re.search(r'- d_model(?: \(.*?\))?: (\d+)',t);depth=re.search(r'- num_layers: (\d+)',t);ff=re.search(r'- d_ff: (\d+)',t)
  if op and lr and dm and depth:cs.append(dict(letter=parts[i],op=op[1],lr=float(lr[1]),dm=int(dm[1]),depth=int(depth[1]),ff=int(ff[1]) if ff else None,gru='self.gru' in t))
 order=re.findall('[A-E]',r['answer']);
 for a,b in itertools.combinations(cs,2):
  if a['op']!=b['op'] or a['op']!='Adagrad' or a['lr']!=b['lr'] or a['lr']>.0001:continue
  def win(x,y):
   if len(order)>1:return order.index(x['letter'])<order.index(y['letter'])
   if order[0]==x['letter']:return True
   if order[0]==y['letter']:return False
   return None
  key=None
  if a['gru']!=b['gru']:x,y=(a,b) if a['gru'] else (b,a);key='GRU'
  elif not a['gru'] and a['dm']==b['dm'] and a['depth']!=b['depth']:x,y=(a,b) if a['depth']>b['depth'] else (b,a);key='deeper'
  elif not a['gru'] and a['dm']==b['dm'] and a['depth']==b['depth'] and a['ff']!=b['ff']:x,y=(a,b) if a['ff']>b['ff'] else (b,a);key='largerFF'
  elif not a['gru'] and a['depth']==b['depth'] and a['dm']!=b['dm']:x,y=(a,b) if a['dm']>b['dm'] else (b,a);key='wider'
  if key and win(x,y) is not None:counts[key].append((r['question_id'],win(x,y),x['letter'],y['letter']))
for k,v in counts.items():print(k,'n',len(v),'hits',sum(x[1] for x in v),'questions',len(set(x[0] for x in v)),v)
